iioc"],"context":["growth-plate-proximal-face"]},{"id":"bv-tv-tibial-iioc","name":"BV/TV, tibial IIOC","description":"ROI-1","source":"deck #6","selectable":true,"kind":"value","unit":"%","on":["roi-iioc"],"context":["growth-plate-proximal-face"],"headline":true},{"id":"iioc-height","name":"IIOC height","description":"middle of the growth plate to the top of the articular bone, vertical","source":"deck #7","expect":["Measured along the shaft axis (the deck value), with the perpendicular height and the growth-plate plane residual beside it; which the lab means is open."],"selectable":true,"kind":"value","unit":"mm","on":["iioc-height-ruler"],"context":["roi-iioc","growth-plate-proximal-face","articular-surface"]},{"id":"iioc-height-medial-compartment","name":"IIOC height, medial compartment","description":"as #7, medial","source":"deck #8","expect":["Measured along the shaft axis (the deck value), with the perpendicular height and the growth-plate plane residual beside it; which the lab means is open."],"selectable":true,"kind":"value","unit":"mm","on":["iioc-medial-ruler"],"context":["roi-iioc","growth-plate-proximal-face","articular-surface"]},{"id":"iioc-height-lateral-compartment","name":"IIOC height, lateral compartment","description":"as #7, lateral","source":"deck #9","expect":["Measured along the shaft axis (the deck value), with the perpendicular height and the growth-plate plane residual beside it; which the lab means is open."],"selectable":true,"kind":"value","unit":"mm","on":["iioc-lateral-ruler"],"context":["roi-iioc","growth-plate-proximal-face","articular-surface"]},{"id":"tibial-width-at-the-growth-plate","name":"Tibial width at the growth plate","description":"centre of the fibula–tibia junction on the tibial surface to the prominent point on the other side (open question for the lab: confirm the endpoints on one annotated scan)","source":"deck #10","expect":["From the centre of the fibula–tibia junction on the tibial surface to the most prominent point on the other side, as /workflow/workflows/mouse-oa/skills/mouse-oa/examples/README.md (iioc) describes."],"selectable":true,"kind":"value","unit":"mm","on":["tibial-width-ruler"],"context":["growth-plate-proximal-face"]},{"id":"subchondral-bone-plate-thickness-medial","name":"Subchondral bone plate thickness, medial","description":"medial plate","source":"deck #11","selectable":true,"kind":"value","unit":"mm","on":["roi-subchondral-plate-medial"],"context":["articular-surface"]},{"id":"subchondral-bone-plate-thickness-lateral","name":"Subchondral bone plate thickness, lateral","description":"lateral plate","source":"deck #12","selectable":true,"kind":"value","unit":"mm","on":["roi-subchondral-plate-lateral"],"context":["articular-surface"]},{"id":"tv-iioc-trab","name":"TV, IIOC-trab","description":"ROI-2: ROI-1 minus the subchondral plate and the cortical line next to the growth plate","source":"deck #13","selectable":true,"kind":"value","unit":"mm3","on":["roi-iioc-trabecular"],"context":["under-plate-boundary"]},{"id":"bv-iioc-trab","name":"BV, IIOC-trab","description":"ROI-2","source":"deck #14","selectable":true,"kind":"value","unit":"mm3","on":["roi-iioc-trabecular"],"context":["under-plate-boundary"]},{"id":"bv-tv-iioc-trab","name":"BV/TV, IIOC-trab","description":"ROI-2","source":"deck #15","selectable":true,"kind":"value","unit":"%","on":["roi-iioc-trabecular"],"context":["under-plate-boundary"]},{"id":"metaphyseal-tv","name":"TV, proximal tibial trabeculae","description":"ROI-3: a band below the growth plate, clear of cortical bone (offsets in protocol.json)","source":"deck #16","selectable":true,"kind":"value","unit":"mm3","on":["roi-metaphyseal"],"context":["growth-plate-distal-face"]},{"id":"metaphyseal-bv","name":"BV, proximal tibial trabeculae","description":"ROI-3","source":"deck #17","selectable":true,"kind":"value","unit":"mm3","on":["roi-metaphyseal"],"context":["growth-plate-distal-face"]},{"id":"metaphyseal-bv-tv","name":"BV/TV, proximal tibial trabeculae","description":"ROI-3","source":"deck #18","selectable":true,"kind":"value","unit":"%","on":["roi-metaphyseal"],"context":["growth-plate-distal-face"]},{"id":"metaphyseal-tb-n","name":"Tb.N, proximal tibial trabeculae","description":"ROI-3","source":"deck #19","selectable":true,"kind":"value","unit":"1/mm","on":["roi-metaphyseal"],"context":["growth-plate-distal-face"]},{"id":"metaphyseal-tb-th","name":"Tb.Th, proximal tibial trabeculae","description":"ROI-3, largest contained sphere","source":"deck #20","selectable":true,"kind":"value","unit":"mm","on":["roi-metaphyseal"],"context":["growth-plate-distal-face"]},{"id":"metaphyseal-tb-sp","name":"Tb.Sp, proximal tibial trabeculae","description":"ROI-3, largest contained sphere in marrow","source":"deck #21","selectable":true,"kind":"value","unit":"mm","on":["roi-metaphyseal"],"context":["growth-plate-distal-face"]},{"id":"metaphyseal-tb-nd","name":"Tb.Nd, trabecular nodes","description":"ROI-3, 3D skeleton junctions of ≥3 struts (the lab reports a count per tissue volume)","source":"deck #22","selectable":true,"kind":"value","unit":"1/mm3","on":["roi-metaphyseal"],"context":["growth-plate-distal-face"]},{"id":"metaphyseal-tb-tm","name":"Tb.Tm, trabecular ends","description":"ROI-3, skeleton free ends (the lab reports a count per tissue volume)","source":"deck #23","selectable":true,"kind":"value","unit":"1/mm3","on":["roi-metaphyseal"],"context":["growth-plate-distal-face"]},{"id":"cortical-thickness-100-um-below-the-growth-plate","name":"Cortical thickness, 100 µm below the growth plate","description":"cortical shell at that level","source":"deck #24","selectable":true,"kind":"value","unit":"mm","on":["roi-cortex-100um"],"context":["cortex","growth-plate-distal-face"]},{"id":"cortical-thickness-1000-um-below-the-growth-plate","name":"Cortical thickness, 1000 µm below the growth plate","description":"as #24","source":"deck #25","selectable":true,"kind":"value","unit":"mm","on":["roi-cortex-1000um"],"co