ace to the most prominent point on the other side, as /workflow/workflows/mouse-oa/skills/mouse-oa/examples/README.md (iioc) describes."],"selectable":true,"kind":"value","unit":"mm","on":["tibial-width-ruler"],"context":["growth-plate-proximal-face"]},{"id":"subchondral-bone-plate-thickness-medial","name":"Subchondral bone plate thickness, medial","description":"medial plate","source":"deck #11","selectable":true,"kind":"value","unit":"mm","on":["roi-subchondral-plate-medial"],"context":["articular-surface"]},{"id":"subchondral-bone-plate-thickness-lateral","name":"Subchondral bone plate thickness, lateral","description":"lateral plate","source":"deck #12","selectable":true,"kind":"value","unit":"mm","on":["roi-subchondral-plate-lateral"],"context":["articular-surface"]},{"id":"tv-iioc-trab","name":"TV, IIOC-trab","description":"ROI-2: ROI-1 minus the subchondral plate and the cortical line next to the growth plate","source":"deck #13","selectable":true,"kind":"value","unit":"mm3","on":["roi-iioc-trabecular"],"context":["under-plate-boundary"]},{"id":"bv-iioc-trab","name":"BV, IIOC-trab","description":"ROI-2","source":"deck #14","selectable":true,"kind":"value","unit":"mm3","on":["roi-iioc-trabecular"],"context":["under-plate-boundary"]},{"id":"bv-tv-iioc-trab","name":"BV/TV, IIOC-trab","description":"ROI-2","source":"deck #15","selectable":true,"kind":"value","unit":"%","on":["roi-iioc-trabecular"],"context":["under-plate-boundary"]},{"id":"metaphyseal-tv","name":"TV, proximal tibial trabeculae","description":"ROI-3: a band below the growth plate, clear of cortical bone (offsets in protocol.json)","source":"deck #16","selectable":true,"kind":"value","unit":"mm3","on":["roi-metaphyseal"],"context":["growth-plate-distal-face"]},{"id":"metaphyseal-bv","name":"BV, proximal tibial trabeculae","description":"ROI-3","source":"deck #17","selectable":true,"kind":"value","unit":"mm3","on":["roi-metaphyseal"],"context":["growth-plate-distal-face"]},{"id":"metaphyseal-bv-tv",